package com.chronos.education.grade.model;
import com.chronos.model.pojo.BaseEntity; import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Getter @Setter @NoArgsConstructor @Table(name="edu_gradebook",uniqueConstraints=@UniqueConstraint(name="uk_edu_gradebook_active_offering_scheme",columnNames={"offering_id","scheme_id"}))
public class Gradebook extends BaseEntity { @Column(name="school_id",nullable=false,length=64) private String schoolId; @Column(name="offering_id",nullable=false,length=64) private String offeringId; @Column(name="scheme_id",nullable=false,length=64) private String schemeId; @Column(name="teacher_id",nullable=false,length=64) private String teacherId; @Column(nullable=false,length=24) private String status="DRAFT"; @Column(name="submission_no",nullable=false) private Integer submissionNo=0; @Column(name="workflow_instance_id",length=64) private String workflowInstanceId; @Column(name="submitted_at") private LocalDateTime submittedAt; @Column(name="published_at") private LocalDateTime publishedAt; @Version @Column(name="row_version",nullable=false) private Long rowVersion=0L; }
